// Batch insights (SPEC §15.1) generated by rules, not by the LLM, plus the threshold sanity check (G9.7)
// and the two backlog insights: city saturation and untapped demand.

import { nearestStore } from "@/lib/engine/cannibalisation";
import type { EngineResult } from "@/lib/engine/types";
import { isLocationReliable } from "@/lib/geo/pins";
import { CITIES } from "@/lib/policy/allowedValues";
import type { BrandProfile } from "@/lib/policy/types";
import { EXISTING_STORES } from "@/data/existingStores";
import { STATUSES, type Status } from "@/lib/types";

export const ISSUE_LABEL: Record<string, string> = {
  A01: "missing required details",
  A02: "a pin code that isn't 6 digits",
  A03: "a pin code that doesn't match the city",
  A04: "a state or city outside our plan",
  A05: "a duplicate application ID",
  A06: "a likely duplicate application",
  A07: "an implausible investment amount",
  A11: "notes that contradict the form",
  A16: "a possible conflict of interest",
};

export interface Insight {
  id: string;
  title: string;
  text: string;
  /** Where to look next: an application filter or a territory. */
  link?: { kind: "status"; status: Status } | { kind: "territory"; id: string } | { kind: "flag"; code: string };
}

export interface ThresholdWarning {
  rule: string;
  affected: number;
  total: number;
  /** "Capital below minimum: 9 of 20" */
  text: string;
}

export interface SaturationInsight {
  city: string;
  territoryIds: string[];
  freePins: number;
  insidePins: number;
  uncertainPins: number;
  radiusKm: number;
  /** True when every free pin is known to be inside; false when some pins have uncertain locations. */
  complete: boolean;
  text: string;
}

export interface DemandInsight {
  total: number;
  cities: { city: string; tier: string; applicants: { appId: string; pin: string | null; readiness: number }[]; meanReadiness: number }[];
  text: string;
}

export interface BatchInsights {
  total: number;
  statusCounts: Record<Status, number>;
  oversubscribed: Insight[];
  emptySlots: Insight[];
  topHoldReason: (Insight & { code: string; count: number }) | null;
  contradictions: Insight | null;
  outsideTerritory: Insight | null;
  saturation: SaturationInsight[];
  untappedDemand: DemandInsight | null;
  topFlags: { code: string; text: string; count: number }[];
  warnings: ThresholdWarning[];
}

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
const idOrder = new Intl.Collator("en", { numeric: true });
const FLAG_LABEL: Record<string, string> = {
  CANNIBALISATION_RISK: "Close to an existing store",
  LOCATION_UNCERTAIN: "Pin location uncertain",
  PAYBACK_WARNING: "Slow payback",
  TARGET_NOT_FEASIBLE: "Target launch not realistic",
  TIGHT_TIMELINE: "Tight timeline",
  NOTES_TARGET_DISAGREE: "Notes and target disagree",
  RENT_BURDEN_RISK: "Rent burden risk",
  PROVISIONAL: "Provisional",
  HUMAN_OVERRIDE: "Human override",
  LOCKED: "Sent to partner",
  INTEGRITY_CONCERN: "Instructions in notes ignored",
  EXPERIENCE_UNDER_REPORTED: "Experience under-reported",
};

/** The fraction of the pool one rule may touch before we tell the user their assumptions may not fit (G9.7). */
export const SANITY_THRESHOLD = 0.4;

/**
 * If a single rule affects more than 40% of applicants, say so: it tells the judge the system knows its
 * assumptions might not fit their data.
 */
export function thresholdWarnings(result: EngineResult): ThresholdWarning[] {
  const total = result.decisions.length;
  if (total === 0) return [];
  const rules: { rule: string; match: (d: EngineResult["decisions"][number]) => boolean }[] = [
    { rule: "Capital below the tier minimum", match: (d) => d.bands?.capital === 1 || d.reasonCodes.includes("BELOW_HARD_FLOOR") },
    { rule: "No space identified", match: (d) => d.bands?.space === 1 || d.reasonCodes.includes("PROFILE_REJECT_SPACE") },
    { rule: "Floor not suitable", match: (d) => d.reasonCodes.includes("FLOOR_NOT_SUITABLE") || d.reasonCodes.includes("PROFILE_REJECT_FLOOR") },
    { rule: "No relevant experience", match: (d) => d.bands?.experience === 1 },
    { rule: "City outside the current plan", match: (d) => d.reasonCodes.includes("OUTSIDE_PLAN") },
    { rule: "Pin already has a store or is in no territory", match: (d) => d.reasonCodes.includes("PIN_HAS_EXISTING_STORE") || d.reasonCodes.includes("PIN_NOT_IN_TERRITORY") },
  ];
  const out: ThresholdWarning[] = [];
  for (const r of rules) {
    const affected = result.decisions.filter(r.match).length;
    if (affected / total > SANITY_THRESHOLD) out.push({ rule: r.rule, affected, total, text: `${r.rule}: ${affected} of ${total}` });
  }
  // Blocking data issues, one rule per check.
  const byCode = new Map<string, Set<string>>();
  for (const i of result.issues) {
    if (i.severity === "blocking" && i.code.startsWith("A")) byCode.set(i.code, (byCode.get(i.code) ?? new Set()).add(i.subjectId));
  }
  for (const [code, apps] of [...byCode].sort(([a], [b]) => a.localeCompare(b))) {
    if (apps.size / total > SANITY_THRESHOLD) {
      const label = ISSUE_LABEL[code] ?? code;
      out.push({ rule: `Data check: ${label}`, affected: apps.size, total, text: `Data check (${label}): ${apps.size} of ${total}` });
    }
  }
  return out;
}

/** City saturation (docs/BACKLOG.md): every remaining territory pin in a city is inside an existing store's inner radius. */
export function citySaturation(result: EngineResult, profile: BrandProfile): SaturationInsight[] {
  const reservedPins = new Set(result.decisions.filter((d) => d.pin).map((d) => d.pin!));
  const byCity = new Map<string, EngineResult["territories"]>();
  for (const t of result.territories) {
    if (t.blocked || !t.city || !t.tier) continue;
    byCity.set(t.city, [...(byCity.get(t.city) ?? []), t]);
  }
  const out: SaturationInsight[] = [];
  for (const city of [...byCity.keys()].sort()) {
    const ters = byCity.get(city)!;
    const free: { pin: string; radius: number }[] = [];
    for (const t of ters) {
      const radius = profile.cannibalisationRadiusKm[t.tier as keyof BrandProfile["cannibalisationRadiusKm"]];
      for (const pin of t.pins) if (!reservedPins.has(pin)) free.push({ pin, radius });
    }
    if (free.length === 0) continue;
    let inside = 0;
    let uncertain = 0;
    for (const f of free) {
      if (!isLocationReliable(f.pin)) {
        uncertain++;
        continue;
      }
      const s = nearestStore(f.pin, EXISTING_STORES);
      if (s && s.km <= f.radius) inside++;
    }
    const reliable = free.length - uncertain;
    // Only pins with reliable coordinates count as "inside"; saturated means every free pin is known to be inside.
    if (inside === 0 || inside !== reliable) continue;
    const radius = Math.min(...free.map((f) => f.radius));
    const complete = uncertain === 0;
    out.push({
      city,
      territoryIds: ters.map((t) => t.id),
      freePins: free.length,
      insidePins: inside,
      uncertainPins: uncertain,
      radiusKm: radius,
      complete,
      text: complete
        ? `${city} looks saturated: every free territory pin (${free.length}) is within ${radius} km of an existing store. Any new partner here will compete with one.`
        : `${city} may be saturated: all ${inside} free pin${inside === 1 ? "" : "s"} with a known location ${inside === 1 ? "is" : "are"} within ${radius} km of an existing store, and ${uncertain} other pin${uncertain === 1 ? " has" : "s have"} an uncertain location.`,
    });
  }
  return out;
}

/** Untapped demand (docs/BACKLOG.md): qualified applicants in cities with no territory, and where to open one. */
export function untappedDemand(result: EngineResult): DemandInsight | null {
  const pool = result.decisions.filter((d) => d.talentPool && d.status === "WAITLIST");
  if (pool.length === 0) return null;
  const byCity = new Map<string, typeof pool>();
  for (const d of pool) byCity.set(d.talentPool!, [...(byCity.get(d.talentPool!) ?? []), d]);
  const cities = [...byCity].map(([city, list]) => {
    const applicants = list
      .map((d) => ({ appId: d.appId, pin: d.homePin, readiness: d.bands ? d.bands.space + d.bands.capital + d.bands.experience : 0 }))
      .sort((a, b) => idOrder.compare(a.appId, b.appId));
    const mean = applicants.reduce((s, a) => s + a.readiness, 0) / applicants.length;
    return { city, tier: CITIES[city as keyof typeof CITIES]?.tier ?? "", applicants, meanReadiness: Math.round(mean * 10) / 10 };
  });
  cities.sort((a, b) => b.applicants.length - a.applicants.length || b.meanReadiness - a.meanReadiness || a.city.localeCompare(b.city));
  const names = cities.map((c) => c.city);
  const list = names.length > 1 ? `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}` : names[0];
  const recs = cities.map((c) => `${c.city} (${plural(c.applicants.length, "qualified applicant")}, readiness ${c.meanReadiness} of 9)`).join("; ");
  return {
    total: pool.length,
    cities,
    text: `${plural(pool.length, "qualified applicant")} in ${list} ${pool.length === 1 ? "has" : "have"} no territory to join. Consider opening territories there, in this order: ${recs}.`,
  };
}

export function buildBatchInsights(result: EngineResult, profile: BrandProfile): BatchInsights {
  const total = result.decisions.length;
  const statusCounts = Object.fromEntries(STATUSES.map((s) => [s, result.decisions.filter((d) => d.status === s).length])) as Record<Status, number>;

  // Applicants per territory: those whose own pin is in it. Eligible ones compete for the slots; holds are counted apart.
  const wanting = new Map<string, number>();
  const onHold = new Map<string, number>();
  for (const d of result.decisions) {
    if (!d.territoryId || d.status === "REJECT") continue;
    const m = d.status === "HOLD" ? onHold : wanting;
    m.set(d.territoryId, (m.get(d.territoryId) ?? 0) + 1);
  }

  const oversubscribed: Insight[] = [];
  const emptySlots: Insight[] = [];
  for (const t of result.territories) {
    if (t.blocked) continue;
    const n = wanting.get(t.id) ?? 0;
    const holds = onHold.get(t.id) ?? 0;
    if (n > t.slots) {
      oversubscribed.push({
        id: `over-${t.id}`,
        title: `${t.id} is oversubscribed`,
        text: `${t.id}: ${plural(n, "eligible applicant")} for ${plural(t.slots, "slot")}${holds ? `, plus ${holds} on hold` : ""}.`,
        link: { kind: "territory", id: t.id },
      });
    }
    const free = t.slots - t.reserved.length;
    if (n + holds === 0 && t.slots > 0 && free > 0) {
      emptySlots.push({
        id: `empty-${t.id}`,
        title: `${t.id} has no applicants`,
        text: `${t.id}: ${plural(free, "free slot")} and no applicants.`,
        link: { kind: "territory", id: t.id },
      });
    }
  }
  oversubscribed.sort((a, b) => idOrder.compare(a.id, b.id));

  // Most common hold reason.
  const holdKeys = new Set(result.decisions.filter((d) => d.status === "HOLD").map((d) => d.appKey));
  const byCode = new Map<string, Set<string>>();
  for (const i of result.issues) {
    if (i.severity === "blocking" && i.code.startsWith("A") && holdKeys.has(i.subjectId)) byCode.set(i.code, (byCode.get(i.code) ?? new Set()).add(i.subjectId));
  }
  const ranked = [...byCode].sort(([ac, a], [bc, b]) => b.size - a.size || ac.localeCompare(bc));
  const top = ranked[0];
  const topHoldReason = top
    ? {
        id: "hold-reason",
        code: top[0],
        count: top[1].size,
        title: "Most common reason for a hold",
        text: `${top[1].size} of ${holdKeys.size} on-hold applicants have ${ISSUE_LABEL[top[0]] ?? top[0]}.`,
        link: { kind: "status" as const, status: "HOLD" as const },
      }
    : null;

  // Contradictions found.
  const countIssue = (code: string) => new Set(result.issues.filter((i) => i.code === code).map((i) => i.subjectId)).size;
  const notesVsForm = countIssue("A11");
  const spaceMismatch = countIssue("A09");
  const dateMismatch = result.decisions.filter((d) => d.reasonCodes.includes("NOTES_TARGET_DISAGREE")).length;
  const contradictionCount = notesVsForm + spaceMismatch + dateMismatch;
  const contradictions: Insight | null = contradictionCount
    ? {
        id: "contradictions",
        title: "Contradictions found",
        text: `${plural(contradictionCount, "contradiction")} between applicants' notes and their forms: ${[
          notesVsForm ? `${notesVsForm} notes vs form` : "",
          spaceMismatch ? `${spaceMismatch} "no space" with a size or floor given` : "",
          dateMismatch ? `${dateMismatch} notes vs target launch date` : "",
        ]
          .filter(Boolean)
          .join(", ")}.`,
      }
    : null;

  // Outside every territory.
  const outside = result.decisions.filter((d) => d.reasonCodes.includes("OUTSIDE_PLAN") || d.reasonCodes.includes("PIN_NOT_IN_TERRITORY"));
  const outsideTerritory: Insight | null = outside.length
    ? {
        id: "outside",
        title: "Applicants outside every territory",
        text: `${plural(outside.length, "applicant")} ${outside.length === 1 ? "is" : "are"} outside every territory: ${outside.map((d) => d.appId).join(", ")}.`,
      }
    : null;

  // Top flags.
  const flagCounts = new Map<string, number>();
  for (const d of result.decisions) for (const f of d.flags) flagCounts.set(f.code, (flagCounts.get(f.code) ?? 0) + 1);
  const topFlags = [...flagCounts]
    .map(([code, count]) => ({ code, text: FLAG_LABEL[code] ?? code, count }))
    .sort((a, b) => b.count - a.count || a.code.localeCompare(b.code))
    .slice(0, 6);

  return {
    total,
    statusCounts,
    oversubscribed,
    emptySlots,
    topHoldReason,
    contradictions,
    outsideTerritory,
    saturation: citySaturation(result, profile),
    untappedDemand: untappedDemand(result),
    topFlags,
    warnings: thresholdWarnings(result),
  };
}
